begin;
set local search_path=public,extensions;
select plan(33);
grant usage on schema extensions to authenticated;
grant execute on all functions in schema extensions to authenticated;

select ok((select count(*)=7 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relkind='r' and c.relname=any(array['provider_payable_events','provider_statements','provider_statement_lines','provider_invoices','provider_payments','provider_reconciliation_batches','provider_payment_allocations'])),'all provider billing records exist');
select ok((select count(*)=7 and bool_and(c.relrowsecurity) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['provider_payable_events','provider_statements','provider_statement_lines','provider_invoices','provider_payments','provider_reconciliation_batches','provider_payment_allocations'])),'RLS is restrictive on every provider billing table');
select ok((select count(*)=5 and bool_and(p.prosecdef and p.proconfig::text like '%search_path=%') from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['record_provider_payable_event','issue_provider_statement','issue_provider_invoice','record_provider_payment','reconcile_provider_payment'])),'five billing commands are security definer with fixed search paths');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['record_provider_payable_event','issue_provider_statement','issue_provider_invoice','record_provider_payment','reconcile_provider_payment']) and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))),'anonymous and service roles cannot execute provider billing commands');
select ok((select count(*)=5 and bool_and(has_function_privilege('authenticated',p.oid,'EXECUTE')) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=any(array['record_provider_payable_event','issue_provider_statement','issue_provider_invoice','record_provider_payment','reconcile_provider_payment'])),'authenticated receives explicit command execution');
select ok(not has_table_privilege('authenticated','public.provider_payable_events','INSERT') and not has_table_privilege('authenticated','public.provider_invoices','UPDATE') and not has_table_privilege('authenticated','public.provider_payments','DELETE') and not has_table_privilege('authenticated','public.provider_payment_allocations','INSERT'),'direct financial mutations are denied');
select ok((select count(*)=7 from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname=any(array['provider_payable_events','provider_statements','provider_statement_lines','provider_invoices','provider_payments','provider_reconciliation_batches','provider_payment_allocations']) and t.tgname like '%_immutable' and not t.tgisinternal),'all provider billing records are immutable');
select ok((select count(*)=7 from pg_policies where schemaname='public' and tablename=any(array['provider_payable_events','provider_statements','provider_statement_lines','provider_invoices','provider_payments','provider_reconciliation_batches','provider_payment_allocations'])),'tenant read policy covers every billing table');
select ok(not exists(select 1 from information_schema.columns where table_schema='public' and table_name=any(array['provider_payable_events','provider_statements','provider_statement_lines','provider_invoices','provider_payments','provider_reconciliation_batches','provider_payment_allocations']) and data_type in('real','double precision')),'provider billing never stores floating-point money');
select ok((select count(*)>=16 from information_schema.columns where table_schema='public' and table_name=any(array['provider_payable_events','provider_statements','provider_statement_lines','provider_invoices','provider_payments','provider_reconciliation_batches','provider_payment_allocations']) and column_name like '%_minor' and data_type='bigint'),'money is consistently represented in bigint minor units');
select ok((select count(*)=1 from pg_constraint where conrelid='public.provider_payable_events'::regclass and contype='f' and pg_get_constraintdef(oid) like '%tax_rule_version_id%'),'payable events reference a versioned fiscal rule');
select ok((select count(*)>=2 from pg_constraint where conrelid='public.provider_payable_events'::regclass and contype='f' and (pg_get_constraintdef(oid) like '%mission_id%' or pg_get_constraintdef(oid) like '%contract_version_id%')),'payables preserve mission and contract-version provenance');
select ok((select count(*)=2 from pg_constraint where conrelid='public.provider_invoices'::regclass and contype='f' and pg_get_constraintdef(oid) like '%provider_organization_id%' and (pg_get_constraintdef(oid) like '%statement_id%' or pg_get_constraintdef(oid) like '%journal_id%')),'invoice statement and journal references are tenant-bound');
select ok((select count(*)=1 from pg_constraint where conrelid='public.provider_payments'::regclass and contype='f' and pg_get_constraintdef(oid) like '%provider_organization_id%' and pg_get_constraintdef(oid) like '%journal_id%'),'payment journal reference is tenant-bound');
select ok((select count(*)=1 from pg_constraint where conrelid='public.provider_invoices'::regclass and contype='c' and pg_get_constraintdef(oid) like '%jsonb_typeof(tax_rule_snapshot)%array%'),'invoice preserves its immutable fiscal-rule snapshot set');
select ok((select count(*)=1 from pg_constraint where conrelid='public.provider_statement_lines'::regclass and contype='u' and pg_get_constraintdef(oid) like '%payable_event_id%'),'one payable event can enter only one statement');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.provider_invoices'::regclass and contype='u' and pg_get_constraintdef(oid) like '%statement_id%'),'a statement can issue only one immutable invoice');
select ok((select count(*)>=1 from pg_constraint where conrelid='public.provider_payments'::regclass and contype='u' and pg_get_constraintdef(oid) like '%provider_organization_id, payment_reference%'),'payment references are unique inside a provider tenant');
select ok((select count(*)=1 from pg_constraint where conrelid='public.provider_payment_allocations'::regclass and contype='u' and pg_get_constraintdef(oid) like '%payment_id, invoice_id%'),'duplicate payment-to-invoice allocations are impossible');
select ok((select reloptions @> array['security_invoker=true'] from pg_class where oid='public.provider_invoice_balances'::regclass),'invoice balance view executes with invoker security');
select ok((select pg_get_viewdef('public.provider_invoice_balances'::regclass,true) like '%PARTIALLY_PAID%' and pg_get_viewdef('public.provider_invoice_balances'::regclass,true) like '%OVERDUE%'),'invoice status is derived from immutable allocations and due date');
select ok((select pg_get_functiondef(p.oid) like '%tax_rule_versions%' and pg_get_functiondef(p.oid) ~ 'status[[:space:]]*=[[:space:]]*''ACTIVE''' and pg_get_functiondef(p.oid) ~ 'jurisdiction_code[[:space:]]*=[[:space:]]*''MA''' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_provider_payable_event'),'payable calculation resolves an active dated Morocco tax version');
select ok((select pg_get_functiondef(p.oid) like '%commission_rule_snapshot%' and pg_get_functiondef(p.oid) like '%floor(%' and pg_get_functiondef(p.oid) like '%numeric%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_provider_payable_event'),'commission and tax rounding use exact versioned inputs');
select ok((select pg_get_functiondef(p.oid) like '%IDEMPOTENCY_PAYLOAD_MISMATCH%' and pg_get_functiondef(p.oid) like '%for update%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname='begin_provider_billing_command'),'billing idempotence rejects payload changes and serializes replay');
select ok((select pg_get_functiondef(p.oid) like '%pg_advisory_xact_lock%' and pg_get_functiondef(p.oid) like '%NO_UNSTATEMENTED_PAYABLES%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='issue_provider_statement'),'statement composition prevents concurrent double inclusion');
select ok((select pg_get_functiondef(p.oid) like '%PROVIDER_COMMISSION_INVOICE%' and pg_get_functiondef(p.oid) like '%''DEBIT''%' and pg_get_functiondef(p.oid) like '%''CREDIT''%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='issue_provider_invoice'),'invoice command posts a balanced double-entry journal');
select ok((select pg_get_functiondef(p.oid) like '%PROVIDER_PAYMENT%' and pg_get_functiondef(p.oid) like '%''DEBIT''%' and pg_get_functiondef(p.oid) like '%''CREDIT''%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_provider_payment'),'payment command posts a balanced double-entry journal');
select ok((select pg_get_functiondef(p.oid) like '%for update%' and pg_get_functiondef(p.oid) like '%PAYMENT_OVERALLOCATED%' and pg_get_functiondef(p.oid) like '%INVOICE_OVERALLOCATED_OR_NOT_FOUND%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='reconcile_provider_payment'),'reconciliation locks the payment and rejects over-allocation');
select ok((select pg_get_functiondef(p.oid) like '%provider.payable.recorded%' and pg_get_functiondef(p.oid) like '%ProviderPayableRecordedV1%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_provider_payable_event'),'payable recording emits audit and Outbox evidence');
select ok((select pg_get_functiondef(p.oid) like '%provider.statement.issued%' and pg_get_functiondef(p.oid) like '%ProviderStatementIssuedV1%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='issue_provider_statement'),'statement issuance emits audit and Outbox evidence');
select ok((select pg_get_functiondef(p.oid) like '%provider.invoice.issued%' and pg_get_functiondef(p.oid) like '%ProviderInvoiceIssuedV1%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='issue_provider_invoice'),'invoice issuance emits audit and Outbox evidence');
select ok((select pg_get_functiondef(p.oid) like '%provider.payment.recorded%' and pg_get_functiondef(p.oid) like '%ProviderPaymentRecordedV1%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='record_provider_payment'),'payment recording emits audit and Outbox evidence');
select ok((select pg_get_functiondef(p.oid) like '%provider.payment.reconciled%' and pg_get_functiondef(p.oid) like '%ProviderPaymentReconciledV1%' from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='reconcile_provider_payment'),'reconciliation emits audit and Outbox evidence');

select * from finish();
rollback;
